  'diagnostic.blocked': { 'zh-CN': '无法继续：{reason}', 'zh-TW': '無法繼續：{reason}', en: 'Blocked: {reason}', ko: '계속할 수 없음: {reason}', ja: '続行できません：{reason}', de: "Blockiert: {reason}", fr: "Bloqué : {reason}", it: "Bloccato: {reason}", 'es-ES': "Bloqueado: {reason}", ru: "Заблокировано: {reason}", pl: "Zablokowane: {reason}", 'pt-BR': "Bloqueado: {reason}" },
  'diagnostic.compatibleWith': { 'zh-CN': '须与 {names} 兼容', 'zh-TW': '須與 {names} 相容', en: 'Must be compatible with {names}', ko: '{names}와(과) 호환되어야 함', ja: '{names} と互換性が必要です', de: "Muss mit {names} kompatibel sein", fr: "Doit être compatible avec {names}", it: "Deve essere compatibile con {names}", 'es-ES': "Debe ser compatible con {names}", ru: "Совместимость с {names}", pl: "Musi być kompatybilny z {names}", 'pt-BR': "Deve ser compatível com {names}" },
  'diagnostic.duplicateProviders': { 'zh-CN': '同一 GUID 有多个已启用的插件', 'zh-TW': '同一 GUID 有多個已啟用的外掛', en: 'Multiple enabled plugins share this GUID', ko: '같은 GUID를 가진 플러그인이 여러 개 활성화됨', ja: '同じ GUID のプラグインが複数有効です', de: "Mehrere aktivierte Plugins teilen sich dieses GUID", fr: "Plusieurs plugins activés partagent cette GUID", it: "I plugin più abilitati condividono questo GUID", 'es-ES': "Muchos plugins habilitados comparten este GUID", ru: "Несколько плагинов разделяют этот GUID", pl: "Wiele włączonych wtyczek dzieli się tym GUID", 'pt-BR': "Vários plug- ins habilitados compartilham este GUID" },
  'diagnostic.truncated': { 'zh-CN': '还有未展示的依赖路径。', 'zh-TW': '還有未顯示的相依路徑。', en: 'Some dependency paths are not shown.', ko: '표시되지 않은 의존 경로가 있습니다.', ja: '表示されていない依存関係の経路もあります。', de: "Einige Abhängigkeitspfade werden nicht angezeigt.", fr: "Certains chemins de dépendance ne sont pas montrés.", it: "Alcuni percorsi di dipendenza non sono mostrati.", 'es-ES': "No se muestran algunos caminos de dependencia.", ru: "Некоторые пути зависимости не показаны.", pl: "Niektóre ścieżki zależności nie są pokazane.", 'pt-BR': "Alguns caminhos de dependência não são mostrados." },
  reviewSelection: { 'zh-CN': '继续查看整链方案', 'zh-TW': '繼續查看整鏈方案', en: 'Review Complete Plan', ko: '전체 계획 확인', ja: '変更計画を確認', de: "Vollständiger Plan", fr: "Examen Plan complet", it: "Recensione Piano completo", 'es-ES': "Revisión Plan completo", ru: "Обзор полного плана", pl: "Przegląd Kompletny Plan", 'pt-BR': "Rever o Plano Completo" },
